head.script:
/* 프로그램ID */
scwin.pgmId = 'PGJ195M03';

/* 최상단(opener, parent 포함) 기준 함수 */
scwin.isMain = function() {
	return true;
};

/**
 * onPageLoad시 자주쓰는 메뉴 전체 리스트,회원id의 등록된 메뉴 리스트 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.onpageload = function() {
	scscrno.setScPgmId(scwin.pgmId);

	/* 메뉴 */	
	if(!scutilo.isEmpty(scwin.pgmId)){ 
	   $p.main().wfm_side.scope.scwin.menuFocus(scwin.pgmId);
	}

	com.executeSubmission(sbm_selectBmrkMenuLst);
};

scwin.onpageunload = function() {

};

/**
 * 자주쓰느메뉴중 대분류 메뉴 폰트색, [] 체크
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbm_selectBmrkMenuLst_submitdone = function(e) {
	for (var i=0; i<dlt_bmrkMenuAllLst.getTotalRow(); i++) {
		if (dlt_bmrkMenuAllLst.getCellData(i,"cortAuctnComCdLvl") == "2") {
			var temp = dlt_bmrkMenuAllLst.getCellData(i, "cortAuctnComCdNm");
			temp = `<font color='blue'> [ ${temp} ]<font>`;
			dlt_bmrkMenuAllLst.setCellData(i, "cortAuctnComCdNm", temp);
		}
	}
};

/**
 * 오른쪽 환살표 버튼 클릭시 유효성 검사후 데이터 바인딩
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_bmrkMenuAdd_onclick = function(e) {
	var cnt=0;
	if (dlt_userSelectMenu.getTotalRow()==0) {
		scutilo.showMsg(scglblo.MSG.WARN,"선택된 항목이 없습니다.");
		return;
	} else {
		if (dlt_bmrkMenuUserLst.getTotalRow()>=10) {/* 등록 메뉴 10개인지 */
			scutilo.showMsg(scglblo.MSG.WARN,"자주쓰는메뉴는 10까지만 등록 가능합니다.");
			return;
		}
		for(var i=0; i<dlt_userSelectMenu.getTotalRow(); i++) {
			var pgmId = dlt_userSelectMenu.getCellData(i, "menuPgmId");
			/* 중복체크 */
			for(var j=0; j<dlt_bmrkMenuUserLst.getTotalRow(); j++) {
				var realPgmId = dlt_bmrkMenuUserLst.getCellData(j, "menuPgmId");
				if (pgmId==realPgmId) {
					cnt++;
				}
			}
			/* 대분류 메뉴 선택됐는지 체크 */
			if (pgmId.length == 7) {
				scutilo.showMsg(scglblo.MSG.WARN,"대메뉴명은 이동할 수 없습니다.")
				return;
			}
			if (cnt>0) {
				scutilo.showMsg(scglblo.MSG.WARN,"이미등록된 메뉴가 포함되어 있습니다.");
				return;
			}
		}
		dlt_bmrkMenuUserLst.setJSON(dlt_userSelectMenu.getAllJSON(), true);
	}
};

/**
 * 전체 자주쓰는 메뉴에서 선택한 메뉴들 dlt_userSelectMenu의 저장
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.msb_bmrkMenuAllLst_onviewchange = function(info) {
	dlt_userSelectMenu.removeAll();
	var selLst = info.newSelectedIndex.split(" ");
	for (var i =0; i<selLst.length; i++) {
		dlt_userSelectMenu.insertRow(i);
		dlt_userSelectMenu.setCellData(i, "menuPgmName", dlt_bmrkMenuAllLst.getCellData(selLst[i], "cortAuctnComCdNm"));
		dlt_userSelectMenu.setCellData(i, "menuPgmId", dlt_bmrkMenuAllLst.getCellData(selLst[i], "cortAuctnComCd"));
		dlt_userSelectMenu.setCellData(i, "indctTurn", i+1);
	}
};



/**
 * 왼쪽 화살표 버튼 클릭시 선택한 자주쓰는메뉴삭제
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_bmrkMenuDel_onclick = function(e) {
	/* 회원id등록된 자주쓰는 메뉴중 지우려고 선택한 index */
	var delIndex = msb_bmrkMenuUserLst.getSelectedIndex(",").split(",");
	var a = [];
	if (delIndex[0] == '') {
		scutilo.showMsg(scglblo.MSG.WARN,"선택된 항목이 없습니다.");
		return;
	} else {
		for(let i=0; i<delIndex.length; i++) {
			a[i] = dlt_bmrkMenuUserLst.getCellData(delIndex[i], "menuPgmId");
		}
		for(var j = 0; j<dlt_bmrkMenuUserLst.getTotalRow(); j++) {
			for(let idx = 0; idx<a.length; idx++) {
				if (dlt_bmrkMenuUserLst.getCellData(j,"menuPgmId") == a[idx]) {
					dlt_bmrkMenuUserLst.removeRow(j);
				}
			}
		}
	}
};

/**
 * 위에 화살표 버튼 클릭시 순서 변경
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_bmrkMenuUp_onclick = function(e) {
	let tempIndex = msb_bmrkMenuUserLst.getSelectedIndex(",").split(",");
	let index = tempIndex[0];
	dlt_bmrkMenuUserLst.rowMoveUp(index);
};

/**
 * 아래 화살표 버튼 클릭시 순서 변경
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_bmrkMenuDown_onclick = function(e) {
	let tempIndex =msb_bmrkMenuUserLst.getSelectedIndex(",").split(",");
	let index = tempIndex[0];
	dlt_bmrkMenuUserLst.rowMoveDown(index);
};

/**
 * 저장 버튼 클릭시 해당 회원ID 자주쓰는목록에 선택한 메뉴 저장
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_saveBmrkMenu_onclick = function(e) {
	dlt_bmrkMenuUserData.removeAll();
	for(let i =0; i<dlt_bmrkMenuUserLst.getTotalRow(); i++) {
		dlt_bmrkMenuUserData.insertRow(i);
		dlt_bmrkMenuUserData.setCellData(i, "menuPgmId", dlt_bmrkMenuUserLst.getCellData(i, "menuPgmId"));
	}
	scutilo.showMsg(scglblo.MSG.WARN,scutilo.getMsg(pgjmsg.PGJ.S_0002), ()=>{
		com.executeSubmission(sbm_insertBmrkMenuUser);
	})
};

/**
 * 메뉴 저장후 초기화
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbm_insertBmrkMenuUser_submitdone = function(e) {

	scwin.onpageload();
};
